"use client";

import * as React from "react";
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Ink mail Dialog root: owns the open state of one modal window. */
const Dialog = DialogPrimitive.Root;

/** The control that opens the dialog. */
const DialogTrigger = DialogPrimitive.Trigger;

/** Moves the dialog to the end of the document body. */
const DialogPortal = DialogPrimitive.Portal;

/** Closes the dialog. Use it to wrap a Cancel or Done button. */
const DialogClose = DialogPrimitive.Close;

/**
 * Ink mail scrim: a deep black veil with a light blur, so the elevated
 * window is the only lit thing on the page.
 */
const DialogOverlay = React.forwardRef<
  HTMLDivElement,
  WithClassName<DialogPrimitive.Backdrop.Props>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Backdrop
    ref={ref}
    data-slot="dialog-overlay"
    className={cn(
      "fixed inset-0 z-50 bg-(--scrim) backdrop-blur-sm",
      "transition-opacity duration-base ease-out",
      "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
      className,
    )}
    {...props}
  />
));
DialogOverlay.displayName = "DialogOverlay";

/**
 * Ink mail dialog window: the elevated surface step with the 0.75rem popover corner,
 * edged by a white hairline folded into the overlay shadow. It settles in
 * from 98% scale, and a ghost icon button in the corner closes it.
 */
const DialogContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<DialogPrimitive.Popup.Props>
>(({ className, children, ...props }, ref) => (
  <DialogPortal>
    <DialogOverlay />
    <DialogPrimitive.Popup
      ref={ref}
      data-slot="dialog-content"
      className={cn(
        "fixed top-1/2 left-1/2 z-50 grid w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4",
        "rounded-lg bg-popover p-6 text-popover-foreground shadow-(--shadow-overlay) outline-none",
        "transition-[opacity,scale] duration-base ease-out",
        "data-[starting-style]:scale-98 data-[starting-style]:opacity-0",
        "data-[ending-style]:scale-98 data-[ending-style]:opacity-0",
        className,
      )}
      {...props}
    >
      {children}
      <DialogPrimitive.Close
        data-slot="dialog-close"
        className={cn(
          buttonVariants({ variant: "ghost", size: "icon-sm" }),
          "absolute end-4 top-4",
        )}
      >
        <Icon icon="ph:x" className="size-4" aria-hidden="true" />
        <span className="sr-only">Close</span>
      </DialogPrimitive.Close>
    </DialogPrimitive.Popup>
  </DialogPortal>
));
DialogContent.displayName = "DialogContent";

/** The title block at the top of a dialog. It leaves room for the close button. */
const DialogHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="dialog-header"
    className={cn("flex flex-col gap-1.5 pe-8 text-start", className)}
    {...props}
  />
);
DialogHeader.displayName = "DialogHeader";

/**
 * The action row at the foot of a dialog. Buttons stack on a phone with the
 * main action on top, and sit in a row at the end from the small breakpoint.
 */
const DialogFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="dialog-footer"
    className={cn(
      "flex flex-col-reverse gap-2 sm:flex-row sm:justify-end",
      className,
    )}
    {...props}
  />
);
DialogFooter.displayName = "DialogFooter";

/**
 * The dialog title. It renders as an h2, so it sets Inter explicitly and
 * keeps the serif for page display headings only.
 */
const DialogTitle = React.forwardRef<
  HTMLHeadingElement,
  WithClassName<DialogPrimitive.Title.Props>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Title
    ref={ref}
    data-slot="dialog-title"
    className={cn(
      "font-sans text-lg font-medium leading-tight tracking-tight text-foreground",
      className,
    )}
    {...props}
  />
));
DialogTitle.displayName = "DialogTitle";

/** The supporting line under the title, in the muted ink. */
const DialogDescription = React.forwardRef<
  HTMLParagraphElement,
  WithClassName<DialogPrimitive.Description.Props>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description
    ref={ref}
    data-slot="dialog-description"
    className={cn("text-sm text-muted-foreground", className)}
    {...props}
  />
));
DialogDescription.displayName = "DialogDescription";

export {
  Dialog,
  DialogPortal,
  DialogOverlay,
  DialogClose,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
};
